/// Raven `UseSiegeTarget` — use the player who triggered the object to fire the
/// objective's target.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:482-526`
pub fn UseSiegeTarget(
    ctx: GameContext<'_>,
    other: *mut gentity_t,
    en: *mut gentity_t,
    target: *mut c_char,
) {
    unsafe {
        // Raven: "looks like we don't have access to a player, so just use
        // the activating entity" — `ent` is computed but Raven's own body
        // never reads it (only `en`/`other` below); kept for parity with the
        // oracle's dead local.
        let _ent: *mut gentity_t = if en.is_null() || (*en).client.is_null() {
            other
        } else {
            en
        };

        if en.is_null() {
            return;
        }
        if target.is_null() {
            return;
        }

        let targetname_ofs = core::mem::offset_of!(gentity_t, targetname) as c_int;

        let mut t: *mut gentity_t = core::ptr::null_mut();
        loop {
            t = G_Find(ctx, t, targetname_ofs, target as *const c_char);
            if t.is_null() {
                break;
            }
            if t == en {
                // G_Printf("WARNING: Entity used itself.\n") — no format args.
                crate::g_main::G_Printf(ctx, b"WARNING: Entity used itself.\n\0".as_ptr() as *const c_char);
            } else if !(*t).use_.is_none() {
                GlobalUse(t, en, en);
            }
            if (*en).inuse == 0 {
                crate::g_main::G_Printf(ctx, b"entity was removed while using targets\n\0".as_ptr() as *const c_char);
                return;
            }
        }
    }
}

// Raven's `SVF_BROADCAST` svflags `#define` is not yet ported anywhere in the
