// Source: `oracle/oracle/codemp/game/g_public.h:20`
const SVF_BROADCAST: c_int = 0x00000020;

/// Raven `SiegeBroadcast_OBJECTIVECOMPLETE`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:528-540`
pub fn SiegeBroadcast_OBJECTIVECOMPLETE(
    ctx: GameContext<'_>,
    team: c_int,
    client: c_int,
    objective: c_int,
) {
    unsafe {
        let nomatter: vec3_t = [0.0, 0.0, 0.0];

        let te = G_TempEntity(ctx, nomatter, entity_event_t::EV_SIEGE_OBJECTIVECOMPLETE as c_int);
        (*te).r.svFlags |= SVF_BROADCAST;
        (*te).s.eventParm = team;
        (*te).s.weapon = client;
        (*te).s.trickedentindex = objective;
    }
}

