/// Raven `SiegeItemRemoveOwner`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:1338-1349`
pub fn SiegeItemRemoveOwner(
    ent: *mut gentity_t,
    carrier: *mut gentity_t,
) {
    unsafe {
        (*ent).genericValue2 = 0; // Remove picked-up flag
        (*ent).genericValue8 = ENTITYNUM_NONE; // Mark entity carrying us as none

        if !carrier.is_null() {
            let cl = (*carrier).client as *mut gclient_t;
            (*cl).holdingObjectiveItem = 0; // The carrier is no longer carrying us
            (*carrier).r.svFlags &= !SVF_BROADCAST;
        }
    }
}

/// Raven `SiegeItemRespawnEffect` — play the objective-item respawn effect and
/// fire its respawn target.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:1351-1370`
pub fn SiegeItemRespawnEffect(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    newOrg: vec3_t,
) {
    unsafe {
        if !(*ent).target5.is_null() && *(*ent).target5 != 0 {
            G_UseTargets2(ctx, ent, ent, (*ent).target5 as *const c_char);
        }

        if (*ent).genericValue10 == 0 {
            // no respawn effect
            return;
        }

        let upAng: vec3_t = [0.0, 0.0, 1.0];

        // Play it once on the current origin, and once on the origin we're
        // respawning to.
        G_PlayEffectID((*ent).genericValue10, (*ent).r.currentOrigin, upAng);
        G_PlayEffectID((*ent).genericValue10, newOrg, upAng);
    }
}

/// Raven `SiegeItemRespawnOnOriginalSpot`.
///
/// Source: `oracle/oracle/codemp/game/g_saga.c:1372-1380`
pub fn SiegeItemRespawnOnOriginalSpot(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    carrier: *mut gentity_t,
) {
    unsafe {
        SiegeItemRespawnEffect(ctx, ent, (*ent).pos1);
        G_SetOrigin(ent, (*ent).pos1);
        SiegeItemRemoveOwner(ent, carrier);

        // Stop the item from flashing on the radar
        (*ent).s.time2 = 0;
    }
}

